package com.careerconnect.jobportal.controller;
import com.careerconnect.jobportal.repository.JobRepository; import java.time.LocalDate; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping;
@Controller public class HomeController { private final JobRepository jobs; public HomeController(JobRepository jobs){this.jobs=jobs;} @GetMapping("/") public String home(Model m, Authentication authentication){m.addAttribute("jobs",jobs.findTop6ByDeadlineGreaterThanEqualOrderByPostedDateDesc(LocalDate.now()));boolean loggedIn=authentication!=null&&authentication.isAuthenticated()&&!"anonymousUser".equals(authentication.getName());m.addAttribute("loggedIn",loggedIn);if(loggedIn){m.addAttribute("currentUsername",authentication.getName());m.addAttribute("admin",authentication.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN")));}return "home";} }
